package com.bank.eod;

import java.math.BigDecimal;
import java.util.concurrent.RecursiveTask;

// Divide-and-conquer sum of account interest amounts.
public class InterestSumTask extends RecursiveTask<BigDecimal> {
    // Below this many elements, just loop (sequential threshold).
    private static final int THRESHOLD = 10_000;

    private final BigDecimal[] amounts;
    private final int lo;
    private final int hi;

    public InterestSumTask(BigDecimal[] amounts, int lo, int hi) {
        this.amounts = amounts; this.lo = lo; this.hi = hi;
    }

    @Override
    protected BigDecimal compute() {
        int len = hi - lo;
        if (len <= THRESHOLD) {
            // small enough — solve directly, no splitting overhead
            BigDecimal sum = BigDecimal.ZERO;
            for (int i = lo; i < hi; i++) sum = sum.add(amounts[i]);
            return sum;
        }
        int mid = lo + len / 2;
        InterestSumTask left = new InterestSumTask(amounts, lo, mid);
        InterestSumTask right = new InterestSumTask(amounts, mid, hi);
        left.fork();                       // schedule left asynchronously
        BigDecimal rightSum = right.compute();  // compute right on this thread
        BigDecimal leftSum = left.join();       // wait for left result
        return leftSum.add(rightSum);           // combine
    }
}
