package com.bank.eod;

import java.math.BigDecimal;
import java.util.concurrent.ForkJoinPool;
import java.util.logging.Logger;

public class ForkJoinDemo {
    private static final Logger log = Logger.getLogger(ForkJoinDemo.class.getName());

    public static void main(String[] args) {
        int n = 2_000_000;
        BigDecimal[] amounts = new BigDecimal[n];
        for (int i = 0; i < n; i++) amounts[i] = new BigDecimal("5.25");  // Rs 5.25 each

        // Parallel sum using the common ForkJoinPool.
        long t0 = System.nanoTime();
        BigDecimal parallel = ForkJoinPool.commonPool()
                .invoke(new InterestSumTask(amounts, 0, n));
        long parMs = (System.nanoTime() - t0) / 1_000_000;

        // Sequential baseline.
        long t1 = System.nanoTime();
        BigDecimal seq = BigDecimal.ZERO;
        for (BigDecimal a : amounts) seq = seq.add(a);
        long seqMs = (System.nanoTime() - t1) / 1_000_000;

        log.info(() -> "Parallel sum=" + parallel + " in " + parMs + "ms");
        log.info(() -> "Sequential sum=" + seq + " in " + seqMs + "ms");
        log.info(() -> "Match=" + parallel.equals(seq)
                + " | pool parallelism=" + ForkJoinPool.commonPool().getParallelism());
    }
}
