package com.bank.eod;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.concurrent.ForkJoinPool;
import static org.junit.jupiter.api.Assertions.assertEquals;

class InterestSumTaskTest {
    @Test
    void parallelSumMatchesSequential() {
        int n = 50_000;
        BigDecimal[] amounts = new BigDecimal[n];
        for (int i = 0; i < n; i++) amounts[i] = new BigDecimal("2.00");
        BigDecimal result = ForkJoinPool.commonPool().invoke(new InterestSumTask(amounts, 0, n));
        assertEquals(new BigDecimal("100000.00"), result.setScale(2));
    }
}
